require_once __DIR__ . '/includes/auth.php'; require_staff(); $pdo=db();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); if(($_POST['form_action']??'')==='save'){ $pdo->prepare('UPDATE retention_settings SET resident_account_days=?,closed_record_days=?,backup_retention_days=?,updated_by=? WHERE id=1')->execute([max(0,(int)$_POST['resident_account_days']),max(0,(int)$_POST['closed_record_days']),max(0,(int)$_POST['backup_retention_days']),current_user()['id']]);flash('success','Retention policy saved. Records remain protected from deletion.');redirect('retention.php'); } if(($_POST['form_action']??'')==='archive'){ $settings=$pdo->query('SELECT * FROM retention_settings WHERE id=1')->fetch();$stmt=$pdo->prepare("SELECT id,resident_id FROM users WHERE role='resident' AND account_status='expired' AND account_expires_at IS NOT NULL AND account_expires_at < DATE_SUB(CURDATE(), INTERVAL {$settings['resident_account_days']} DAY) AND archived_at IS NULL");$stmt->execute();$targets=$stmt->fetchAll();$archived=0;foreach($targets as $target){$pdo->prepare("UPDATE users SET archived_at=NOW(),account_status='expired' WHERE id=?")->execute([$target['id']]);if($target['resident_id'])$pdo->prepare("UPDATE residents SET status='Archived' WHERE id=? AND status='Moved out'")->execute([$target['resident_id']]);$archived++;}flash('success',"Archive review complete: {$archived} eligible resident account(s) marked as archived. No residents, staff, documents, or reports were deleted.");redirect('retention.php');} }
$settings=$pdo->query('SELECT * FROM retention_settings WHERE id=1')->fetch();$expired=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='resident' AND (account_status='expired' OR (account_expires_at IS NOT NULL AND account_expires_at < CURDATE()))")->fetchColumn();$eligible=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='resident' AND account_status='expired' AND account_expires_at IS NOT NULL AND account_expires_at < DATE_SUB(CURDATE(), INTERVAL {$settings['resident_account_days']} DAY) AND archived_at IS NULL")->fetchColumn();$residentsCount=(int)$pdo->query('SELECT COUNT(*) FROM residents')->fetchColumn();$staffCount=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role IN ('admin','staff')")->fetchColumn();$pageTitle='Data retention';$activePage='retention';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Administration / Governance</div><h1>Data retention policy</h1><p>Keep resident and staff identity records available for audit, continuity, and lawful records management.</p></div><a class="secondary-button" href="backup.php">⇩ Back up records</a></section><div class="priority-banner retention-safe"><span class="priority-icon">✓</span><div><strong>Non-destructive retention is active</strong><small>Residents, staff, documents, reports, and feedback are never deleted by this module. Expired access is disabled; eligible records are only marked Archived.</small></div><span class="muted">Delete actions disabled</span></div><div class="stats-grid"><div class="stat-card"><div class="stat-icon blue">♙</div><span class="stat-label">Resident records protected</span><strong><?= $residentsCount ?></strong><small>Never deleted</small></div><div class="stat-card"><div class="stat-icon violet">♧</div><span class="stat-label">Staff records protected</span><strong><?= $staffCount ?></strong><small>Never deleted</small></div><div class="stat-card"><div class="stat-icon amber">◷</div><span class="stat-label">Expired accounts</span><strong><?= $expired ?></strong><small>Portal access disabled</small></div><div class="stat-card"><div class="stat-icon mint">✓</div><span class="stat-label">Eligible for archive</span><strong><?= $eligible ?></strong><small>Still retained</small></div></div><section class="panel form-panel"><div class="card-header"><div><div class="eyebrow">Policy settings</div><h2>Retention periods</h2></div><span class="muted">Policy does not authorize deletion</span></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="save"><label>Keep expired resident accounts (days)<input type="number" min="0" name="resident_account_days" value="<?= h($settings['resident_account_days']) ?>"><small class="field-help">After this period, expired residents may be marked Archived. Their identity and service history remain available.</small></label><label>Review closed records after (days)<input type="number" min="0" name="closed_record_days" value="<?= h($settings['closed_record_days']) ?>"><small class="field-help">Review-only threshold for closed reports and issued documents. Records are not deleted.</small></label><label>Keep backup logs (days)<input type="number" min="0" name="backup_retention_days" value="<?= h($settings['backup_retention_days']) ?>"><small class="field-help">Backup history remains part of the audit trail; store downloaded files separately.</small></label><div class="form-actions"><button class="primary-button">Save retention policy</button></div></form></section><section class="panel form-panel"><div class="card-header"><div><div class="eyebrow">Maintenance action</div><h2>Mark eligible records as archived</h2><p class="login-copy">This action only changes the label on old expired resident accounts. It does not delete residents, staff, documents, reports, feedback, or backups.</p></div></div><form method="post" onsubmit="return confirm('Mark eligible expired resident accounts as Archived? No records will be deleted.')"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="archive"><button class="primary-button" <?= $eligible===0?'disabled':'' ?>>Mark as archived →</button></form></section><?php require __DIR__.'/partials/footer.php'; ?>
